package com.rental.controller;
import com.rental.dto.ApiResponse; import com.rental.entity.Owner; import com.rental.repository.OwnerRepository; import com.rental.security.AuthPrincipal; import lombok.Data; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/owner/profile") public class OwnerProfileController{private final OwnerRepository repo;private final PasswordEncoder enc;public OwnerProfileController(OwnerRepository r,PasswordEncoder e){repo=r;enc=e;}@GetMapping public ResponseEntity<ApiResponse<Owner>> me(@AuthenticationPrincipal AuthPrincipal p){return ResponseEntity.ok(ApiResponse.ok("Profile fetched",repo.findById(p.id()).orElseThrow()));}@PutMapping public ResponseEntity<ApiResponse<Owner>> update(@AuthenticationPrincipal AuthPrincipal p,@RequestBody Req r){Owner o=repo.findById(p.id()).orElseThrow();if(r.name!=null&&!r.name.isBlank())o.setName(r.name.trim());if(r.phone!=null)o.setPhone(r.phone.trim());return ResponseEntity.ok(ApiResponse.ok("Profile updated",repo.save(o)));}@PatchMapping("/password") public ResponseEntity<ApiResponse<Void>> password(@AuthenticationPrincipal AuthPrincipal p,@RequestBody Pass r){Owner o=repo.findById(p.id()).orElseThrow();if(!enc.matches(r.currentPassword,o.getPassword()))throw new IllegalArgumentException("Current password is incorrect");if(r.newPassword==null||r.newPassword.length()<6)throw new IllegalArgumentException("New password must be at least 6 characters");o.setPassword(enc.encode(r.newPassword));repo.save(o);return ResponseEntity.ok(ApiResponse.ok("Password updated",null));}@Data public static class Req{public String name;public String phone;}@Data public static class Pass{public String currentPassword;public String newPassword;}}
